import { existsSync, readFileSync } from "node:fs"
import { dirname, join } from "node:path"
import { describe, expect, it } from "vitest"
import { ICLINE_BUILD_METADATA } from "./build-metadata"

/**
 * The About page reads its version line from `ICLINE_BUILD_METADATA`, which is
 * GENERATED by `scripts/sync-icline-docs.mjs` — not from `package.json`
 * directly. Twice now (dev.2-fix.2, dev.4-fix.4) the version was bumped and
 * packed without re-running the sync, so VS Code showed the new version while
 * About still showed the old label. Both times the fix was a one-off repack;
 * this test is the guardrail, so the third time fails the suite instead of
 * shipping.
 *
 * The parse rules below mirror `parseVersionParts` in that script — if the
 * script's rules change, update both.
 */
function findExtensionRoot(): string {
	let dir = process.cwd()
	for (let i = 0; i < 6; i++) {
		const pkgPath = join(dir, "package.json")
		if (existsSync(pkgPath)) {
			try {
				const pkg = JSON.parse(readFileSync(pkgPath, "utf8"))
				if (pkg?.name === "iCline" && typeof pkg?.version === "string") {
					return dir
				}
			} catch {
				// Not parseable — keep walking up.
			}
		}
		const parent = dirname(dir)
		if (parent === dir) {
			break
		}
		dir = parent
	}
	throw new Error(`Extension root (package.json with name "iCline") not found from cwd ${process.cwd()}`)
}

function parseVersionParts(version: string): {
	releaseVersion: string
	devBuildNumber: number | null
	devBuildLabel: string | null
} {
	const devMatch = version.match(/^(.+)-dev\.(\d+)(?:-fix\.(\d+))?$/)
	if (devMatch) {
		const fixN = devMatch[3]
		return {
			releaseVersion: devMatch[1],
			devBuildNumber: Number.parseInt(devMatch[2], 10),
			devBuildLabel: fixN ? `dev build ${devMatch[2]} · fix.${fixN}` : `dev build ${devMatch[2]}`,
		}
	}
	const fixMatch = version.match(/^(.+)-fix\.(\d+)$/)
	if (fixMatch) {
		return { releaseVersion: fixMatch[1], devBuildNumber: null, devBuildLabel: `fix.${fixMatch[2]}` }
	}
	return { releaseVersion: version, devBuildNumber: null, devBuildLabel: null }
}

describe("build-metadata freshness", () => {
	it("matches package.json — re-run `node scripts/sync-icline-docs.mjs` after every version bump", () => {
		const extRoot = findExtensionRoot()
		const pkg = JSON.parse(readFileSync(join(extRoot, "package.json"), "utf8"))
		const expected = parseVersionParts(pkg.version)
		expect(
			{
				releaseVersion: ICLINE_BUILD_METADATA.releaseVersion,
				devBuildNumber: ICLINE_BUILD_METADATA.devBuildNumber,
				devBuildLabel: ICLINE_BUILD_METADATA.devBuildLabel,
			},
			`build-metadata.ts is stale for version ${pkg.version}: run \`node scripts/sync-icline-docs.mjs\` from apps/vscode, rebuild the webview, and repack`,
		).toEqual(expected)
	})
})
